@router.patch({{path}}, response_model=ChildRead)
def patch_child(parent_id: int, child_id: int, data: ChildPatch, db: Annotated[Session, Depends(session_provider)]) -> Child:
    """Patch child."""
    row = _require_child(db, parent_id, child_id)
    for name, value in model_values(data, exclude_unset=True).items():
        setattr(row, name, value)
    try:
        db.commit()
    except IntegrityError as exc:
        integrity_failure(db, exc)
    db.refresh(row)
    return row
